"use strict";

// Regression guard for the FLH-SO-0059 amount discrepancy.
//
// A USD order (sold at the campaign's locked ₦/$ rate) had its pay link
// generated by the admin "Send Pay Link" button, which passes NO currency.
// The service used to default to "NGN", so it built a Nomba checkout in Naira;
// Nomba then reconverted that Naira total at its own live rate when the buyer
// paid by international card, charging $708.25 instead of the quoted $764.
//
// The fix: when no currency is supplied, settle in the order's own
// display_currency and convert at the order's LOCKED fx_rate_used. These tests
// assert the gateway receives USD + the whole-dollar figure, and that NGN
// orders still settle in Naira.

const ORDER_USD = {
  order_id: "ord-usd",
  order_number: "FLH-SO-0059",
  status: "pending",
  contact_id: "contact-1",
  sales_campaign_id: "camp-1",
  total_ngn: "992400.00",
  amount_paid_ngn: "0.00",
  display_currency: "USD",
  fx_rate_used: "1300", // locked at placement → ₦992,400 ÷ 1,300 = $763.38
  display_total: "764.00", // the dollar total the landing page quoted
};

const ORDER_NGN = {
  order_id: "ord-ngn",
  order_number: "FLH-SO-0060",
  status: "pending",
  contact_id: "contact-1",
  sales_campaign_id: null,
  total_ngn: "500000.00",
  amount_paid_ngn: "0.00",
  display_currency: null,
  fx_rate_used: null,
};

// A Quick Sale: sold in Naira, no rate of its own (fx_rate_used = column
// default 1.0), no campaign.
const ORDER_QUICK_SALE = {
  order_id: "ord-qs",
  order_number: "FLH-SO-0070",
  status: "pending",
  contact_id: "contact-1",
  sales_campaign_id: null,
  total_ngn: "500000.00",
  amount_paid_ngn: "0.00",
  display_currency: "NGN",
  fx_rate_used: "1.000000",
  public_tracking_token: "tok-qs",
};

let mockOrder = ORDER_USD;
const mockNombaCalls = [];
const mockChainCalls = [];
const mockLocks = [];

jest.mock("../../../src/modules/sales/sales.repo", () => ({
  findById: jest.fn(async () => mockOrder),
  findByPublicToken: jest.fn(async ({ brand, token }) =>
    brand === "faitlynhair" && token === mockOrder.public_tracking_token
      ? mockOrder
      : null,
  ),
  findByOrderNumber: jest.fn(async () => null),
  lockSettlementCurrency: jest.fn(async (args) => {
    mockLocks.push(args);
    return {
      display_currency: args.currency,
      fx_rate_used: args.fx_rate,
      display_total: args.display_total,
    };
  }),
}));

jest.mock("../../../src/utils/brand-urls", () => ({
  payLinkUrl: jest.fn(async () => "https://shop.example.com/pay/tok"),
}));

jest.mock("../../../src/modules/sales_campaigns/campaigns.repo", () => ({
  // Campaign rate intentionally DIFFERS from the order's locked rate to prove
  // we charge the locked fx_rate_used, not the (mutable) live campaign rate.
  findById: jest.fn(async () => ({ ngn_per_usd_rate: 1401 })),
}));

jest.mock("../../../src/modules/business_setup/payment-gateways.service", () => ({
  getActiveChain: jest.fn(async ({ currency }) => {
    mockChainCalls.push(currency);
    return [{ provider: "nomba", credentials: { client_id: "c" } }];
  }),
}));

jest.mock("../../../src/services/nomba.service", () => ({
  initializePayment: jest.fn(async (args) => {
    mockNombaCalls.push(args);
    return { data: { checkoutLink: "https://pay.nomba.com/checkout/xyz" } };
  }),
}));

jest.mock("../../../src/services/paystack.service", () => ({}));
jest.mock("../../../src/services/opay.service", () => ({}));
jest.mock("../../../src/services/stripe.service", () => ({}));

// The catalogue tool's ₦/$ rate is 1,500; no manual currency_rates override.
jest.mock("../../../src/config/database", () => ({
  query: jest.fn(async (sql) => {
    const s = String(sql);
    if (s.includes("catalogue_config")) return { rows: [{ usd_fx_rate: 1500 }] };
    if (s.includes("currency_rates")) return { rows: [] };
    return { rows: [{ email: "buyer@example.com" }] };
  }),
}));

jest.mock("../../../src/config/env", () => ({
  config: { APP_URL: "https://hub.example.com" },
}));

const paymentLink = require("../../../src/modules/sales/payment-link.service");

beforeEach(() => {
  mockNombaCalls.length = 0;
  mockChainCalls.length = 0;
  mockLocks.length = 0;
});

describe("createPaymentLink — settlement currency defaults to the order", () => {
  test("USD order with no currency → Nomba charged in USD at the locked rate", async () => {
    mockOrder = ORDER_USD;
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_USD.order_id,
      amount_ngn: 992400,
      // currency intentionally omitted — mimics the admin "Send Pay Link" button
    });

    expect(mockNombaCalls).toHaveLength(1);
    // Whole-dollar figure at the ORDER's locked 1,300 rate, NOT the 1,401
    // campaign rate (which would give $709) and NOT a Naira figure.
    expect(mockNombaCalls[0].currency).toBe("USD");
    expect(mockNombaCalls[0].amount).toBe("764.00");
    // The gateway chain must be routed by USD, not the default NGN rail.
    expect(mockChainCalls).toContain("USD");
  });

  test("NGN order with no currency → Nomba charged the full Naira total", async () => {
    mockOrder = ORDER_NGN;
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_NGN.order_id,
      amount_ngn: 500000,
    });

    expect(mockNombaCalls).toHaveLength(1);
    expect(mockNombaCalls[0].currency).toBe("NGN");
    expect(mockNombaCalls[0].amount).toBe("500000.00");
    expect(mockChainCalls).toContain("NGN");
  });

  test("explicit currency still wins over the order default", async () => {
    mockOrder = ORDER_USD;
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_USD.order_id,
      amount_ngn: 992400,
      currency: "NGN",
    });
    expect(mockNombaCalls[0].currency).toBe("NGN");
    expect(mockNombaCalls[0].amount).toBe("992400.00");
  });
});

describe("currency lock — NGN + USD only, customers can't switch", () => {
  test("a GBP/EUR checkout is refused before any gateway is called", async () => {
    mockOrder = ORDER_NGN;
    await expect(
      paymentLink.createPaymentLink({
        brand: "faitlynhair",
        order_id: ORDER_NGN.order_id,
        currency: "GBP",
      }),
    ).rejects.toMatchObject({ code: "UNSUPPORTED_CURRENCY" });
    expect(mockNombaCalls).toHaveLength(0);
  });

  test("the public pay link ignores a client-sent currency (no $1 flip on a Naira order)", async () => {
    // The exploit: POST /api/public/pay/:token {amount_ngn: 1500, currency:
    // "USD"} on a Naira order minted a $1 USD checkout.
    mockOrder = ORDER_QUICK_SALE;
    await paymentLink.createPublicPaymentLink({
      token: "tok-qs",
      amount_ngn: 1500,
      currency: "USD",
    });
    expect(mockNombaCalls).toHaveLength(1);
    expect(mockNombaCalls[0].currency).toBe("NGN");
    expect(mockNombaCalls[0].amount).toBe("1500.00");
    expect(mockLocks).toHaveLength(0);
  });

  test("the public pay link on a USD order still charges USD at the locked rate", async () => {
    mockOrder = { ...ORDER_USD, public_tracking_token: "tok-usd" };
    await paymentLink.createPublicPaymentLink({
      token: "tok-usd",
      currency: "NGN",
    });
    expect(mockNombaCalls[0].currency).toBe("USD");
    expect(mockNombaCalls[0].amount).toBe("764.00");
  });

  test("a staff USD link on an unlocked order locks the catalogue-priced dollar total", async () => {
    // One ₦500,000 line with no catalogue USD price → ₦500,000 ÷ 1,500 =
    // 333.33 → $334 (whole-dollar rule for items without a USD price).
    mockOrder = {
      ...ORDER_QUICK_SALE,
      shipping_fee_ngn: "0.00",
      lines: [{ line_kind: "product", variant_id: "var-x", unit_price_ngn: "500000.00", quantity: 1 }],
    };
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_QUICK_SALE.order_id,
      currency: "USD",
    });
    expect(mockLocks).toHaveLength(1);
    expect(mockLocks[0]).toMatchObject({
      brand: "faitlynhair",
      id: ORDER_QUICK_SALE.order_id,
      currency: "USD",
      display_total: "334.00",
    });
    // The effective rate divides the Naira total back to the dollar total.
    expect(Number(mockLocks[0].fx_rate).toFixed(6)).toBe((500000 / 334).toFixed(6));
    // Full balance → the locked dollar total, exactly.
    expect(mockNombaCalls[0].currency).toBe("USD");
    expect(mockNombaCalls[0].amount).toBe("334.00");
  });

  test("a part payment on a USD order converts at the locked rate, to the cent", async () => {
    mockOrder = ORDER_USD;
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_USD.order_id,
      amount_ngn: 100000,
    });
    // ₦100,000 ÷ 1,300 = 76.923 → $76.92
    expect(mockNombaCalls[0].amount).toBe("76.92");
  });

  test("an order already locked to USD is never re-pinned", async () => {
    mockOrder = ORDER_USD;
    await paymentLink.createPaymentLink({
      brand: "faitlynhair",
      order_id: ORDER_USD.order_id,
    });
    expect(mockLocks).toHaveLength(0);
  });
});
